    def forward(self, a, b, ignore=None):
        a, b = F.normalize(a, dim=-1), F.normalize(b, dim=-1)
        logits = a @ b.T * self.t.exp().clamp(max=100) + self.b
        labels = 2 * torch.eye(len(a), device=a.device) - 1
